"""Generate taskapp/models_generated.py from schema/models.json and refresh schema/models.lock."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SCHEMA = ROOT / "schema" / "models.json"
TARGET = ROOT / "taskapp" / "models_generated.py"
LOCK = ROOT / "schema" / "models.lock"

HEADER = (
    "# AUTO-GENERATED by scripts/gen_models.py from schema/models.json.\n"
    "# DO NOT EDIT BY HAND. Change schema/models.json and re-run the generator.\n"
)


def render(schema: dict) -> str:
    lines = [HEADER + f"# schema version: {schema['version']}", "", "from __future__ import annotations", ""]
    lines.append("from dataclasses import dataclass")
    for model in schema["models"]:
        lines += ["", "", "@dataclass", f"class {model['name']}:"]
        for field in model["fields"]:
            if "default" in field:
                lines.append(f"    {field['name']}: {field['type']} = {field['default']}")
            else:
                lines.append(f"    {field['name']}: {field['type']}")
    lines.append("")
    return "\n".join(lines)


def sha256(text: str) -> str:
    return hashlib.sha256(text.replace("\r\n", "\n").encode("utf-8")).hexdigest()


def main() -> int:
    schema = json.loads(SCHEMA.read_text(encoding="utf-8"))
    output = render(schema)
    TARGET.write_text(output, encoding="utf-8", newline="\n")
    lock = {"schema_version": schema["version"], "sha256": sha256(output)}
    LOCK.write_text(json.dumps(lock, indent=2) + "\n", encoding="utf-8", newline="\n")
    print(f"generated taskapp/models_generated.py (schema version {schema['version']})")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
